window.REPLANTEO_TPL="";

;(function(){
const H=window._rh;
window.generarReplanteo=async function(o){
  const d=o.fecha||new Date(),p2=n=>String(n).padStart(2,'0');
  const nameT=H.titulo(o.name),nameU=String(o.name).toUpperCase();
  const side=`FTTH Digi_${o.num} ${nameT} - MIGA ${o.miga}`;
  JSZip.defaults.createFolders=false;
  const zip=await JSZip.loadAsync(window.REPLANTEO_TPL,{base64:true});
  const rep=s=>s.split('{{SIDE}}').join(H.esc(side)).split('{{NAMEU}}').join(H.esc(nameU)).split('{{NAMET}}').join(H.esc(nameT)).split('{{NUM}}').join(H.esc(o.num)).split('{{MIGA}}').join(H.esc(o.miga)).split('{{FECHA}}').join(`${p2(d.getDate())}/${p2(d.getMonth()+1)}/${d.getFullYear()}`).split('{{MESANIO}}').join(H.MESES[d.getMonth()].toUpperCase()+' '+d.getFullYear()).split('{{REAL}}').join(H.esc(o.real||''));
  for(const p of Object.keys(zip.files)){if(/^(ppt\/slideLayouts\/slideLayout\d+\.xml|ppt\/slideMasters\/slideMaster\d+\.xml|ppt\/slides\/slide[123]\.xml|docProps\/app\.xml)$/.test(p)){let x=rep(await zip.file(p).async('string'));
    if(/slide2\.xml$/.test(p))x=x.replace(/<a:br>[\s\S]*?<\/a:br>/g,'</a:p><a:p>');
    if(/slide3\.xml$/.test(p)&&o.titles&&o.titles.length){const ps=o.titles.map(t=>'<a:p><a:r><a:rPr lang="es-ES" sz="2000" dirty="0"/><a:t>'+H.esc(String(t).replace(/[.\s]+$/,'')+'.')+'</a:t></a:r></a:p>').join('');x=x.replace(/(<a:lvl1pPr marL="342900" indent="-342900"><a:lnSpc><a:spcPts val=")3500/,'$13000').replace(/(<\/a:lvl1pPr><\/a:lstStyle>)(?:<a:p>[\s\S]*?<\/a:p>)+(<\/p:txBody><\/p:sp><\/p:spTree>)/,'$1'+ps+'$2')}
    zip.file(p,x)}}
  if(o.cover){const c=await H.prep(o.cover,1500,.85,6102181/6858000);zip.file('ppt/media/image8.jpeg',c.data,{createFolders:false})}
  const X=950000,Y=700000,W=10900000,Hh=4600000;
  for(let s=4;s<=11;s++){
    const sp=`ppt/slides/slide${s}.xml`,rp=`ppt/slides/_rels/slide${s}.xml.rels`;
    let x=await zip.file(sp).async('string'),r=await zip.file(rp).async('string'),add='',rels='';
    const blobs=(o.slides[s]||[]);
    if(blobs.length){
      const items=[];for(const b of blobs)items.push(await H.prep(b,1600,.85));
      const pos=H.layout(items,X,Y,W,Hh,110000);
      items.forEach((it,k)=>{const nm=`ppt/media/rp_${s}_${k+1}.jpeg`;zip.file(nm,it.data,{createFolders:false});const id='rIdF'+(k+1);
        rels+=`<Relationship Id="${id}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/rp_${s}_${k+1}.jpeg"/>`;
        const p=pos[k];add+=`<p:pic><p:nvPicPr><p:cNvPr id="${200+k}" name="Foto ${k+1}"/><p:cNvPicPr><a:picLocks noChangeAspect="1"/></p:cNvPicPr><p:nvPr/></p:nvPicPr><p:blipFill><a:blip r:embed="${id}"/><a:stretch><a:fillRect/></a:stretch></p:blipFill><p:spPr><a:xfrm><a:off x="${p.x}" y="${p.y}"/><a:ext cx="${p.w}" cy="${p.h}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></p:spPr></p:pic>`})
    }else if(o.na&&o.na[s]){
      const m=x.match(/<p:sp>(?:(?!<\/p:sp>).)*?Subt[^>]*>(?:(?!<\/p:sp>).)*<\/p:sp>/s);
      if(m){const runs=m[0].match(/<a:r>.*?<\/a:r>/gs);if(runs){const last=runs[runs.length-1];x=x.replace(m[0],m[0].replace(last,last+last.replace(/<a:t>[^<]*<\/a:t>/,'<a:t> – N/A</a:t>')))}}
    }else{
      add=`<p:sp><p:nvSpPr><p:cNvPr id="200" name="Aviso"/><p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="${X}" y="${Y}"/><a:ext cx="${W}" cy="${Hh}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:noFill/></p:spPr><p:txBody><a:bodyPr wrap="square" anchor="ctr"/><a:lstStyle/><a:p><a:pPr algn="ctr"/><a:r><a:rPr lang="es-ES" sz="2400" dirty="0"><a:solidFill><a:srgbClr val="8C8C8C"/></a:solidFill></a:rPr><a:t>Sin fotografías</a:t></a:r></a:p></p:txBody></p:sp>`
    }
    // notes
    if(s>=4){const tk='{{N'+s+'}}',m=x.match(new RegExp('<a:p>(?:(?!</a:p>).)*'+tk.replace(/[{}]/g,'\\$&')+'.*?</a:p>','s'));
      if(m){const lines=String(o.notes&&o.notes[s]||'').split('\n').map(t=>t.trim()).filter(Boolean);if(!lines.length)lines.push(' ');
        const big=s>=10,top=big?5462415:(s===7?5681599:5786265),fh=big?1077482:746867,avail=(5396758+fh-top)/12700,fixed=7.2+(big?16.8:0),width=807,sz0=big?1200:1400,min=big?800:900;
        let sz=sz0,need=0;for(;;){const cw=sz/100*(big?.58:.53),lh=sz/100*1.2;let n=0;for(const l of lines)n+=Math.max(1,Math.ceil(l.length*cw/width));need=n*lh+fixed;if(need<=avail||sz<=min)break;sz-=50}
        if(need>avail){const extra=Math.round((need-avail)*12700)+40000,ncy=Math.min(fh+extra,6700000-5396758);x=x.replace(new RegExp('(name="Rect[^"]*"(?:(?!</p:sp>).)*?<a:ext cx="10439602" cy=")'+fh+'(")','s'),'$1'+ncy+'$2')}
        const para=m[0].replace(/sz="\d+"/g,'sz="'+sz+'"');
        x=x.replace(m[0],lines.map(l=>para.replace(tk,H.esc(l))).join(''))}}
    x=x.replace('</p:spTree>',add+'</p:spTree>');r=r.replace('</Relationships>',rels+'</Relationships>');
    zip.file(sp,x);zip.file(rp,r)
  }
  return await zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.presentationml.presentation',compression:'DEFLATE',compressionOptions:{level:3}});
};
window.replanteoNombre=function(o){const d=o.fecha||new Date(),p=n=>String(n).padStart(2,'0');return `${String(d.getFullYear()).slice(2)}${p(d.getMonth()+1)}${p(d.getDate())}_Replanteo_Huella_SE-${H.titulo(o.name).replace(/\s+/g,'_')}.pptx`};
})();
